-- ============================================================
-- 潮回りの計算を直す（月齢の近似 → 実際の朔＋旧暦日）
--
-- 報告（2026-08-09）: 「今日は中潮のはずなのに長潮と出る」。
--
-- 原因は 2 つ重なっていた。
--   1. 朔望月の**平均**（29.530588853 日）を 2000 年の朔から積み上げていた。
--      実際の朔は平均から最大 ±0.6 日ずれるので、年を追うごとに合わなくなる。
--   2. **月齢と旧暦日を同じものとして扱っていた**。潮名は旧暦日で決まるが、
--      旧暦日は「朔の日を 1 日目と数える日付」であって、経過時間ではない。
--      朔が夕方（例: 2026-07-14 18:43 JST）だと、その日の正午の月齢はまだ 29 日台
--      なのに旧暦では 1 日。ここで丸ごと 1 日ずれる。
--
-- 検証（気象庁 舞阪 2026 年の潮位表と突合、詳細は D-062）:
--   直す前  長潮の平均日較差 76.4cm > 小潮 66.9cm  … 潮名の順序が壊れている
--   直した後 長潮 66.6cm < 小潮 71.6cm < 若潮 75.3cm < 中潮 97.6 < 大潮 113.6
--   （長潮＝日較差が最小の日、というのが本来の意味）
--
-- 実装方針: 朔の時刻は Meeus の計算式で求まるが、SQL で書くと読めなくなる。
-- フロント（frontend/assets/app.js）と同じ計算で作った**表**を持ち、
-- SQL は引くだけにする。両者が一致することはテストで確認する。
-- 収録範囲は 1990-2080。範囲外は NULL を返す（黙って間違えるよりよい）。
-- ============================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.moon_new_moons (
  new_moon_at TIMESTAMPTZ PRIMARY KEY
);

COMMENT ON TABLE public.moon_new_moons IS
  '朔（新月）の時刻。Meeus「Astronomical Algorithms」49 章で算出（D-062）。1990-2080。';

-- 公開データなので誰でも読めてよい（潮位表と同じ扱い）
ALTER TABLE public.moon_new_moons ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "moon_new_moons: read" ON public.moon_new_moons;
CREATE POLICY "moon_new_moons: read" ON public.moon_new_moons FOR SELECT USING (TRUE);
GRANT SELECT ON public.moon_new_moons TO anon, authenticated;

TRUNCATE public.moon_new_moons;

-- 旧暦日（朔の日を 1 日目とする通日）。潮名はこれで決まる
CREATE OR REPLACE FUNCTION public.lunar_day(target DATE)
RETURNS INTEGER
LANGUAGE sql STABLE
AS $$
  SELECT (target - (m.new_moon_at AT TIME ZONE 'Asia/Tokyo')::date) + 1
  FROM public.moon_new_moons m
  WHERE (m.new_moon_at AT TIME ZONE 'Asia/Tokyo')::date <= target
  ORDER BY m.new_moon_at DESC
  LIMIT 1;
$$;

-- JST 正午時点の月齢。朔が正午より後の日は 29 日台になる（暦の慣習どおり）
CREATE OR REPLACE FUNCTION public.moon_age(target DATE)
RETURNS NUMERIC
LANGUAGE sql STABLE
AS $$
  SELECT ROUND((EXTRACT(EPOCH FROM
      ((target + TIME '12:00') AT TIME ZONE 'Asia/Tokyo') - m.new_moon_at
    ) / 86400.0)::numeric, 1)
  FROM public.moon_new_moons m
  WHERE m.new_moon_at <= (target + TIME '12:00') AT TIME ZONE 'Asia/Tokyo'
  ORDER BY m.new_moon_at DESC
  LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.tide_type(target DATE)
RETURNS TEXT
LANGUAGE sql STABLE
AS $$
  SELECT CASE
    WHEN d IN (1, 2, 3, 15, 16, 17, 18, 29, 30) THEN '大潮'
    WHEN d IN (4, 5, 6, 12, 13, 14, 19, 20, 21, 27, 28) THEN '中潮'
    WHEN d IN (7, 8, 9, 22, 23, 24) THEN '小潮'
    WHEN d IN (10, 25) THEN '長潮'
    WHEN d IN (11, 26) THEN '若潮'
    ELSE NULL     -- 収録範囲外
  END
  FROM (SELECT public.lunar_day(target) AS d) t;
$$;

-- 既に保存した釣果の潮回りを引き直す。
-- これは入力値ではなく釣行日から決まる派生値なので、間違ったまま残す理由がない
UPDATE public.fishing_records r
SET tide_type = public.tide_type(r.fished_at),
    tide_snapshot = COALESCE(r.tide_snapshot, '{}'::jsonb) || jsonb_build_object(
      'tide_type', public.tide_type(r.fished_at),
      'moon_age',  public.moon_age(r.fished_at),
      'method',    'lunar_day')
WHERE public.tide_type(r.fished_at) IS NOT NULL
  AND r.tide_type IS DISTINCT FROM public.tide_type(r.fished_at);

COMMIT;
